export const UNITY_2D_MOVEMENT_TEMPLATE = `using UnityEngine;

/// <summary>
/// 2D Platformer Player Controller
/// Handles movement, jumping, and basic physics
/// Generated by ORBITAI Game Mechanics Service
/// </summary>
public class PlayerController : MonoBehaviour
{
    [Header("Movement Settings")]
    [Tooltip("Horizontal movement speed")]
    public float moveSpeed = {{MOVE_SPEED}}f;
    
    [Tooltip("Jump force applied when jumping")]
    public float jumpForce = {{JUMP_FORCE}}f;
    
    [Tooltip("Maximum number of jumps allowed (1 = single jump, 2 = double jump)")]
    public int maxJumps = {{MAX_JUMPS}};
    
    [Header("Ground Detection")]
    [Tooltip("Layer mask for ground detection")]
    public LayerMask groundLayer;
    
    [Tooltip("Offset for ground check position")]
    public Vector2 groundCheckOffset = new Vector2(0f, -0.5f);
    
    [Tooltip("Size of ground check box")]
    public Vector2 groundCheckSize = new Vector2(0.8f, 0.1f);
    
    // Private variables
    private Rigidbody2D rb;
    private int jumpsRemaining;
    private bool isGrounded;
    private float moveInput;
    
    void Start()
    {
        rb = GetComponent<Rigidbody2D>();
        if (rb == null)
        {
            Debug.LogError("PlayerController requires a Rigidbody2D component!");
        }
        jumpsRemaining = maxJumps;
    }
    
    void Update()
    {
        // Get input
        moveInput = Input.GetAxisRaw("Horizontal");
        
        // Check if grounded
        CheckGrounded();
        
        // Reset jumps when grounded
        if (isGrounded)
        {
            jumpsRemaining = maxJumps;
        }
        
        // Jump input
        if (Input.GetKeyDown(KeyCode.Space) && jumpsRemaining > 0)
        {
            Jump();
        }
        
        // Flip sprite based on movement direction
        if (moveInput > 0)
        {
            transform.localScale = new Vector3(1f, 1f, 1f);
        }
        else if (moveInput < 0)
        {
            transform.localScale = new Vector3(-1f, 1f, 1f);
        }
    }
    
    void FixedUpdate()
    {
        // Apply horizontal movement
        rb.velocity = new Vector2(moveInput * moveSpeed, rb.velocity.y);
    }
    
    private void Jump()
    {
        // Reset vertical velocity for consistent jumps
        rb.velocity = new Vector2(rb.velocity.x, 0f);
        
        // Apply jump force
        rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);
        
        // Decrease remaining jumps
        jumpsRemaining--;
    }
    
    private void CheckGrounded()
    {
        // Use box cast for ground detection
        Vector2 checkPosition = (Vector2)transform.position + groundCheckOffset;
        isGrounded = Physics2D.OverlapBox(checkPosition, groundCheckSize, 0f, groundLayer);
    }
    
    // Visualize ground check in editor
    void OnDrawGizmos()
    {
        Gizmos.color = isGrounded ? Color.green : Color.red;
        Vector2 checkPosition = (Vector2)transform.position + groundCheckOffset;
        Gizmos.DrawWireCube(checkPosition, groundCheckSize);
    }
}
`;

